# Convert the list of dictionaries to a pandas DataFrame
df = pd.DataFrame(data)


def map_ncbi_to_ensembl(ncbi_ids):
    # Join the list of NCBI IDs into a single string with commas
    if isinstance(ncbi_ids, list):
        ncbi_ids = ','.join(ncbi_ids)
    
    # Split the input string by comma, semicolon, whitespace, or newline
    ncbi_ids_list = re.split(r'[,\s;]+|\n+', ncbi_ids.strip())
    # print('ncbi  -->', ncbi_ids_list)
    
    ensembl_ids = []
    for ncbi_id in ncbi_ids_list:
        result = df.loc[df['NCBI'] == ncbi_id, 'ETID']
        if not result.empty:
            ensembl_ids.append(result.values[0])
    
    return ensembl_ids

ncbi = works.param(1)
# print ( ncbi )
if not ncbi:
    works.resolve ( ncbi )
else:    
    mapped_ensembl_id = map_ncbi_to_ensembl(ncbi)
    works.resolve ( mapped_ensembl_id )
